-- 014_post_juli_2026.sql
-- Newsletter-Post vom 31.07.2026 (created_at = 12:00 Europe/Zurich).

insert into public.posts (slug, title, description, body, image_path, published, created_at)
values (
  'juli-2026',
  'Juli 2026',
  'Europapark Golf Rang 22, Bonmont Open Top 10, Direktqualifikation in die Q-School Second Stage — und das 4. MG Invitational in Domat/Ems.',
  $BODY$Nach diesen intensiven Wochen hatte ich endlich mal etwas Zeit, um Pause zu machen – aber gleichzeitig auch nicht, denn diese zwei Wochen habe ich genutzt, um mit meinen Albatros-Gönnern und Sponsoren meine Golfrunden zu planen. So konnte ich ein, zwei Tage Pause machen, Runden spielen und das etwas als Erhaltungstraining nutzen, zudem für mich wichtige Termine abhaken und im Schwung bleiben. Dazwischen konnte ich die Zeit mit meinem Umfeld geniessen, auch mal zwei Tage zuhause auf dem Sofa verbringen und Administrationsaufgaben erledigen sowie mein Gönnerturnier final organisieren.

Europapark Golf

Dann stand bereits der nächste Event vor der Türe: das Turnier auf dem Europapark Golfplatz. Die Anreise war einmal kurz und somit angenehm, jedoch hat der Platz in den letzten beiden Wochen sehr gelitten, sodass auf der Proberunde schnell bemerkbar wurde, dass diese Woche etwas speziell werden könnte. Die Fairways waren braun und steinhart, also keine Rede mehr von Fairways, was die Bounces vom Tee und ums Green unvorhersehbar machte – und ab und zu hat auch etwas Glück und Pech dazu beigetragen.

Ich starte nicht optimal ins Turnier und muss auf den ersten zwei Löchern bereits zwei Wasserbälle in Kauf nehmen, was die erste Runde sehr anstrengend machte, denn ich war seit Loch 1 im Hintertreffen und musste 17 Löcher kämpfen, um zurückzukommen – was mir nur bedingt gelang. Ich kann die Runde aber mit 2 über beenden und bin im Mittelfeld. Die zweite Runde ist fast noch schlimmer als die erste, denn der Location und den Konditionen entsprechend spiele ich wie eine Achterbahn: gerade mal 6 Pars, dafür viele Birdies, aber ebenso viele Bogeys. Eine sehr anstrengende Runde, die ich mit 1 über Par beende – ich mache den Cut, bleibe aber irgendwo im Mittelfeld.

Die Finalrunde dann ähnlich auf und ab: Ich spiele gut, mache aber immer wieder kleine Fehler, die aufgrund der Konditionen doppelt bestraft werden. Am Ende spiele ich an einem windigen Tag 1 über Par, kann noch ein paar Plätze gutmachen und beende das Turnier auf dem 22. Rang.

Bonmont Open

Zwei Tage Maintenance-Training am Zürichsee, dann geht's bereits weiter nach Bonmont. Ich freue mich auf das «Heimturnier» und reise zwei Tage vor Beginn an, spiele die Proberunden auf dem super gewässerten, saftig grünen Golfplatz. Die erste Runde ist aber wieder eine komplette Achterbahn: Ich mache viele Birdies und ein Eagle, muss aber 5 Bogeys in Kauf nehmen aufgrund von schlechtem Kurzspiel und einem Wasserball. Ich kann aber eine solide Runde von 2 unter Par ins Clubhaus bringen.

Die zweite Runde spiele ich genau das Spiel, das ich mir vorstelle, muss nur ein Bogey in Kauf nehmen, kann aber auf den ersten 14 Löchern fast keine Chancen verwerten, was mich nervt. Ich bleibe aber geduldig und kann dann mit einem genialen Finish – Birdie, Birdie, Eagle, Birdie – einen riesigen Sprung nach vorne machen und die Runde perfekt abschliessen mit 6 unter Par.

Auch in der Finalrunde beginnt es sehr harzig, und ich bekomme die Birdie-Chancen nicht verwertet. Ich muss also geduldig bleiben und weiter Chancen erarbeiten, was mir gelingt. Auch in der letzten Finalrunde, mit viel Druck, gelingt es mir, mein bestes Golf abzurufen, und mit 2 Birdies auf den letzten 4 Löchern sichere ich mir mein zehntes Top-10-Resultat der Saison und kann meine Position in den Top 5 im Ranking verteidigen.

BONUS Q-School

Mit meiner Rangierung in den Top 5 sichere ich mir die Direktqualifikation in die zweite Stufe der DP World Tour Qualifying School und kann somit im September die First Stage überspringen. Offiziell ist es erst am 11. August, aber da die Pro Golf Tour bis dahin keine Turniere mehr austrägt, kann ich es bereits verkünden. Das freut mich sehr, denn eine Woche Pause im September ist genau das, was ich brauche, denn genau um diese Zeit finden auch die letzten beiden Pro Golf Tour Turniere statt, wo ich den Fokus klar hochhalten möchte. Zudem ermöglicht mir diese Direktqualifikation eine weitere Option auf eine HotelPlanner Tour oder sogar eine DP World Tour Kategorie für die kommende Saison.

MG Supporter Invitational

{{IMAGE:/brand-assets/images/blog/mg-invitational-2026.png|MG Supporter Invitational 2026 — Klinik und Austausch in Domat/Ems, Foto: stauffi.com}}

Am 31. Juli fand das 4. MG Invitational in Domat/Ems statt. Ein wichtiger Tag für mich, um DANKE zu sagen an genau die Personen, die mich auf meinem Weg begleiten und unterstützen und somit einer der wichtigsten Bausteine in meiner spielerischen und persönlichen Entwicklung sind.

Der Tag hatte von Hitze und Sonnenschein bis zum Gewitterabbruch alles mit dabei. In der Klinik am Vormittag konnte ich ein paar Insights zu meinen Trainingsmethoden und Schwunggedanken mitteilen und gewisse Fragen beantworten, die man sonst eventuell nicht so einfach erklären kann. Danach ging es auf den Platz zu einem gemütlichen Scramble, bei dem ich mich wie jedes Jahr von Flight zu Flight mitspielend alle 2 Löcher zufallen liess. Leider hat es aufgrund des Gewitterabbruchs nicht für alle gereicht, dafür konnte ich dann bei einem gemütlichen Abendessen einen etwas tieferen Einblick in meine laufende Saison und einen Ausblick auf den Rest der Saison geben, ein paar mehr Fragen beantworten, mich mit allen austauschen, noch individuelle Fragen beantworten und den Abend gemeinsam ausklingen lassen.

DANKE an alle 40 Anwesenden und alle, die mich auf meinem Weg begleiten. Ich schätze jeden Support und hoffe, den einen oder anderen mal auf dem Golfplatz zu sehen.`,
  image_path: "/brand-assets/images/blog/mg-invitational-2026.png",
  created_at: JULI_2026_CREATED_AT,
};
$BODY$,
  '/brand-assets/images/blog/mg-invitational-2026.png',
  true,
  '2026-07-31T10:00:00.000Z'
)
on conflict (slug) do update set
  title = excluded.title,
  description = excluded.description,
  body = excluded.body,
  image_path = excluded.image_path,
  published = excluded.published,
  created_at = excluded.created_at;
